@startuml
!define RECTANGLE class
!define RECTANGLEWithTitle class

title UML Testing Profile (UTP) for Requirements U35_13

' Nonfunctional Requirements
RECTANGLEWithTitle "Nonfunctional Requirements" {
  RECTANGLE "VIRTUA-13-17" {
    :Support Hospital's and Government of India emerging needs based on the data gathered and analysed by the system.
  }
  RECTANGLE "VIRTUA-13-18" {
    :Ensure confidentiality and privacy of Patient data.
  }
  RECTANGLE "VIRTUA-13-19" {
    :Only authorized Hospital staff (Doctors) should have access to Patients Consultation requests.
  }
  RECTANGLE "VIRTUA-13-20" {
    :Chemists and Labs should be shown data only on National Institute of Technology, Surathkal, Karnataka need to know basis.
  }
  RECTANGLE "VIRTUA-13-21" {
    :High availability is very important.
  }
  RECTANGLE "VIRTUA-13-22" {
    :The system needs to be highly reliable.
  }
  RECTANGLE "VIRTUA-13-23" {
    :Screens have to be designed for Usability i.e. large font size.
  }
}

' Functional Requirement
RECTANGLEWithTitle "Functional Requirement" {
  RECTANGLE "Req-14" {
    :Every Month Administration will improve the Disease Prediction Database with learning of the prior month.
  }
}

@enduml
